const LOGO_BASE64 = "data:image/png;base64,";

const HTML_TEMPLATE = `
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>YL 账号中心</title>
<style>
  :root { --bg: #fff; --text: #000; --line: #111; --blue: #3582e7; --muted: #888; }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: #fafafa; height: 100vh; display: flex; justify-content: center; align-items: center; }
  
  .auth-card { background: var(--bg); border: 6px solid var(--line); border-radius: 8px; width: 100%; max-width: 360px; padding: 30px 24px; display: none; position: relative; }
  .auth-card.active { display: block; }

  .header { display: flex; align-items: center; gap: 12px; margin-bottom: 30px; }
  .header img { width: 48px; height: 48px; object-fit: cover; border-radius: 8px; }
  .header h2 { font-size: 22px; font-weight: 700; color: #000; letter-spacing: 1px; }

  .form-group { margin-bottom: 20px; }
  .form-group label { display: block; font-size: 16px; font-weight: 700; margin-bottom: 8px; color: #000; }
  .input-box { width: 100%; height: 44px; border: 4px solid var(--line); border-radius: 4px; padding: 0 12px; font-size: 16px; outline: none; background: transparent; font-weight: 500;}
  .input-box:focus { border-color: var(--blue); }

  .code-row { display: flex; gap: 10px; align-items: stretch; }
  .code-row .input-box { flex: 1; }
  .btn-get-code { width: 90px; border: 4px solid var(--line); background: transparent; font-weight: 700; font-size: 14px; cursor: pointer; border-radius: 4px; color: #000;}
  .btn-get-code:disabled { color: #888; border-color: #888; }

  .btn-primary { width: 100%; height: 50px; background: var(--blue); border: none; border-radius: 4px; color: #000; font-size: 18px; font-weight: 700; margin-top: 10px; cursor: pointer; transition: 0.2s; }
  .btn-primary:active { opacity: 0.8; }
  .btn-outline { width: 100%; height: 50px; background: transparent; border: 4px solid var(--line); border-radius: 4px; color: #000; font-size: 18px; font-weight: 700; margin-top: 10px; cursor: pointer; }

  .footer-links { display: flex; justify-content: space-between; margin-top: 20px; font-size: 14px; font-weight: 700; }
  .footer-links a { color: var(--blue); text-decoration: none; cursor: pointer; }

  .avatar-large { width: 100px; height: 100px; border: 4px solid var(--line); border-radius: 50%; margin: 0 auto 20px; display: block; object-fit: cover; cursor: pointer; background: #eee; transition: opacity 0.2s; }
  .avatar-large:hover { opacity: 0.8; }
  .profile-name { text-align: center; font-size: 22px; font-weight: 700; margin-bottom: 40px; cursor: pointer; transition: color 0.2s; }
  .profile-name:hover { color: var(--blue); }

  .modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.4); display: none; justify-content: center; align-items: center; z-index: 100; }
  .modal-overlay.active { display: flex; }
  .modal-box { background: var(--bg); border: 4px solid var(--line); padding: 24px; width: 90%; max-width: 320px; text-align: center; }
  .modal-box h3 { font-size: 18px; margin-bottom: 16px; }
  .modal-box input { width: 100%; border: 4px solid var(--line); padding: 12px; font-size: 16px; outline: none; margin-bottom: 20px; background: transparent; font-weight: bold;}
  .modal-actions { display: flex; justify-content: center; gap: 12px; }
  .modal-actions button { flex: 1; padding: 10px; border: 4px solid var(--line); background: transparent; font-size: 15px; font-weight: 700; cursor: pointer; }
  .modal-actions button.primary { background: var(--blue); color: #000; border-color: var(--blue); }
</style>
</head>
<body>

  <div class="auth-card" id="view-about">
    <div class="header">
      <img class="smart-logo" alt="YL">
      <h2>YL 账户中心</h2>
    </div>
    <div id="about-profile" style="display: none;">
      <img class="avatar-large" id="about-avatar" src="" title="点击修改头像" onclick="changeAvatar()">
      <div class="profile-name" id="about-name" title="点击修改昵称" onclick="promptName()">用户</div>
      <button class="btn-outline" onclick="logout()">退出登录</button>
    </div>
    <div id="about-login-btn" style="display: none;">
      <p style="text-align: center; color: #888; margin-bottom: 20px;">您尚未登录</p>
      <button class="btn-primary" onclick="switchView('login')">前往登录</button>
    </div>
  </div>

  <div class="auth-card" id="view-authorize">
    <div class="header">
      <img class="smart-logo" alt="YL">
      <h2>授权登录</h2>
    </div>
    <p style="font-size: 16px; line-height: 1.6; margin-bottom: 24px; text-align: center;">
      <b id="auth-client-name" style="color: var(--blue); font-size: 18px;"></b><br>
      正在尝试请求您的账号信息，是否同意？
    </p>
    <button class="btn-primary" onclick="handleAuthorize(true)">同意授权</button>
    <button class="btn-outline" onclick="handleAuthorize(false)">不授权</button>
  </div>

  <div class="auth-card" id="view-login">
    <div class="header">
      <img class="smart-logo" alt="YL">
      <h2>登录YL账号</h2>
    </div>
    <div class="form-group"><label>邮箱</label><input type="email" id="login-email" class="input-box"></div>
    <div class="form-group"><label>密码</label><input type="password" id="login-pwd" class="input-box"></div>
    <button class="btn-primary" onclick="doLogin()">登录</button>
    <div class="footer-links"><a onclick="switchView('register')">注册账号</a><a onclick="switchView('reset')">忘记密码</a></div>
  </div>

  <div class="auth-card" id="view-register">
    <div class="header">
      <img class="smart-logo" alt="YL">
      <h2>注册YL账号</h2>
    </div>
    <div class="form-group"><label>用户名</label><input type="text" id="reg-name" class="input-box" placeholder="比如：张三"></div>
    <div class="form-group"><label>邮箱</label><input type="email" id="reg-email" class="input-box"></div>
    <div class="form-group">
      <label>验证码</label>
      <div class="code-row"><input type="text" id="reg-code" class="input-box"><button class="btn-get-code" id="btn-reg-code" onclick="sendCode('reg-email', 'btn-reg-code')">点击获取</button></div>
    </div>
    <div class="form-group"><label>密码</label><input type="password" id="reg-pwd" class="input-box"></div>
    <button class="btn-primary" onclick="doRegister()">注册</button>
    <div class="footer-links"><a onclick="switchView('login')">返回登录</a></div>
  </div>

  <div class="auth-card" id="view-reset">
    <div class="header">
      <img class="smart-logo" alt="YL">
      <h2>密码重置</h2>
    </div>
    <div class="form-group"><label>邮箱</label><input type="email" id="reset-email" class="input-box"></div>
    <div class="form-group">
      <label>验证码</label>
      <div class="code-row"><input type="text" id="reset-code" class="input-box"><button class="btn-get-code" id="btn-reset-code" onclick="sendCode('reset-email', 'btn-reset-code')">点击获取</button></div>
    </div>
    <div class="form-group"><label>新密码</label><input type="password" id="reset-pwd" class="input-box"></div>
    <button class="btn-primary" onclick="doReset()">点击重置</button>
    <div class="footer-links"><a onclick="switchView('login')">返回登录</a></div>
  </div>

  <div class="modal-overlay" id="name-modal">
    <div class="modal-box">
      <h3>修改昵称</h3>
      <input type="text" id="new-name-input" placeholder="请输入新昵称">
      <div class="modal-actions">
        <button onclick="document.getElementById('name-modal').classList.remove('active')">取消</button>
        <button class="primary" onclick="saveName()">确认</button>
      </div>
    </div>
  </div>

<script>
  const API_BASE = "";
  const LOGO_URL = "https://data.cstcloud.cn/api/file/download/file/07436cf5-e708-4830-a900-5cf8560e7af7-4f45644423506e86bcaaef2257d4cd3d";
  const FALLBACK_BASE64 = "\\\${LOGO_BASE64}";

  document.querySelectorAll('.smart-logo').forEach(img => {
    let timer = setTimeout(() => { img.src = FALLBACK_BASE64; }, 3000);
    img.onload = () => { clearTimeout(timer); };
    img.onerror = () => { clearTimeout(timer); img.src = FALLBACK_BASE64; };
    img.src = LOGO_URL;
  });

  const urlParams = new URLSearchParams(window.location.search);
  const returnUrl = urlParams.get('returnUrl') || "";
  const clientId = urlParams.get('client') || "";
  
  let userEmail = localStorage.getItem("acss_email") || null;
  // 不再依赖本地缓存的名字和头像作为最终真相，而是由服务器拉取
  let userName = localStorage.getItem("acss_name") || null;
  let userAvatar = localStorage.getItem("acss_avatar") || "";
  const defaultAvatar = "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23333' stroke-width='2'><path d='M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2'></path><circle cx='12' cy='7' r='4'></circle></svg>";

  function switchView(viewName) {
    document.querySelectorAll('.auth-card').forEach(el => el.classList.remove('active'));
    document.getElementById('view-' + viewName).classList.add('active');
  }

  // 核心：每次刷新或加载，向后端请求最新真实数据
  async function loadProfileFromDB() {
    if (!userEmail) return;
    try {
      const res = await fetch(API_BASE + "/api/get-profile?email=" + encodeURIComponent(userEmail));
      if (res.ok) {
        const data = await res.json();
        if (data.success) {
          userName = data.nickname || userEmail;
          userAvatar = data.avatar || "";
          localStorage.setItem("acss_name", userName);
          localStorage.setItem("acss_avatar", userAvatar);
        }
      }
    } catch (e) { console.error("拉取资料失败"); }
  }

  async function init() {
    document.getElementById('about-profile').style.display = 'none';
    document.getElementById('about-login-btn').style.display = 'none';

    if (!userEmail) {
      if (returnUrl) switchView('login');
      else { 
        switchView('about'); 
        document.getElementById('about-login-btn').style.display = 'block'; 
      }
      return;
    }
    
    // 已登录：先去拉最新数据
    await loadProfileFromDB();

    if (returnUrl) {
      switchView('authorize');
      let appName = "未知网站";
      if (clientId === "ylbbs") appName = "YL BBS";
      else if (clientId === "ylnewtab") appName = "YL New Tab";
      else { try { appName = new URL(returnUrl).hostname; } catch(e) { appName = returnUrl; } }
      document.getElementById('auth-client-name').innerText = appName;
    } else {
      switchView('about');
      document.getElementById('about-profile').style.display = 'block';
      document.getElementById('about-name').innerText = userName;
      document.getElementById('about-avatar').src = userAvatar || defaultAvatar;
    }
  }

  function changeAvatar() {
    const input = document.createElement("input"); 
    input.type = "file"; input.accept = "image/*";
    input.onchange = (e) => {
      const file = e.target.files[0]; 
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement("canvas"); 
          const ctx = canvas.getContext("2d");
          const size = 150; canvas.width = size; canvas.height = size;
          ctx.drawImage(img, 0, 0, size, size);
          const base64 = canvas.toDataURL("image/jpeg", 0.8);
          
          fetch(API_BASE + "/api/profile", {
            method: "POST", 
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ email: userEmail, avatar: base64 })
          }).then(() => {
            userAvatar = base64;
            localStorage.setItem("acss_avatar", base64);
            document.getElementById('about-avatar').src = base64;
          });
        };
        img.src = ev.target.result;
      };
      reader.readAsDataURL(file);
    };
    input.click();
  }

  function promptName() {
    document.getElementById('new-name-input').value = userName;
    document.getElementById('name-modal').classList.add('active');
  }

  function saveName() {
    const newName = document.getElementById('new-name-input').value.trim();
    if (!newName) return;
    fetch(API_BASE + "/api/profile", {
      method: "POST", 
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email: userEmail, nickname: newName })
    }).then(() => {
      userName = newName;
      localStorage.setItem("acss_name", newName);
      document.getElementById('about-name').innerText = newName;
      document.getElementById('name-modal').classList.remove('active');
    });
  }

  async function handleAuthorize(agree) {
    if (!agree) { window.location.href = returnUrl + (returnUrl.includes('?') ? '&' : '?') + 'error=access_denied'; return; }
    const token = btoa(userEmail + ":" + Date.now());
    window.location.href = returnUrl + (returnUrl.includes('?') ? '&' : '?') + 'token=' + token + '&username=' + encodeURIComponent(userName) + '&avatar=' + encodeURIComponent(userAvatar);
  }

  async function sendCode(inputId, btnId) {
    const email = document.getElementById(inputId).value.trim();
    if (!email) return alert("请输入邮箱");
    const btn = document.getElementById(btnId); btn.disabled = true; btn.innerText = "发送中...";
    try {
      const res = await fetch(API_BASE + '/api/send-code', { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email }) });
      if (res.ok) {
        let cd = 50; btn.innerText = cd + "s";
        const t = setInterval(() => { cd--; if (cd <= 0) { clearInterval(t); btn.disabled = false; btn.innerText = "点击获取"; } else { btn.innerText = cd + "s"; } }, 1000);
      } else { alert("发送失败"); btn.disabled = false; btn.innerText = "点击获取"; }
    } catch (e) { alert("网络错误"); btn.disabled = false; btn.innerText = "点击获取"; }
  }

  async function doLogin() {
    const email = document.getElementById("login-email").value.trim();
    const password = document.getElementById("login-pwd").value;
    if (!email || !password) return alert("请填写完整");
    try {
      const res = await fetch(API_BASE + '/api/login', { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email, password }) });
      const data = await res.json();
      if (res.ok) {
        localStorage.setItem("acss_email", data.email); 
        userEmail = data.email;
        await loadProfileFromDB(); // 登录后直接拉取最新资料
        init();
      } else alert(data.error || "登录失败");
    } catch (e) { alert("网络错误"); }
  }

  async function doRegister() {
    const nickname = document.getElementById("reg-name").value.trim();
    const email = document.getElementById("reg-email").value.trim();
    const code = document.getElementById("reg-code").value.trim();
    const password = document.getElementById("reg-pwd").value;
    if (!nickname || !email || !code || !password) return alert("请填全信息");
    try {
      const res = await fetch(API_BASE + '/api/register', { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ nickname, email, code, password }) });
      if (res.ok) { alert("注册成功！"); switchView("login"); } else alert(await res.text());
    } catch (e) { alert("网络错误"); }
  }

  async function doReset() { alert("重置密码功能暂未开放"); }

  function logout() {
    localStorage.removeItem("acss_email"); 
    localStorage.removeItem("acss_name"); 
    localStorage.removeItem("acss_avatar");
    window.location.reload();
  }

  init();
</script>
</body>
</html>
`;

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname.startsWith("/api/")) {
      const corsHeaders = { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Methods": "GET, POST, OPTIONS", "Access-Control-Allow-Headers": "Content-Type" };
      if (request.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
      async function hashPassword(pwd) {
        const b = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(pwd));
        return Array.from(new Uint8Array(b)).map(x => x.toString(16).padStart(2, '0')).join('');
      }
      try {
        if (request.method === "POST" && url.pathname === "/api/send-code") {
          const { email } = await request.json();
          const code = Math.floor(100000 + Math.random() * 900000).toString();
          const exp = new Date(Date.now() + 5 * 60 * 1000).toISOString();
          await env.DB.prepare("INSERT OR REPLACE INTO verify_codes (email, code, expires_at) VALUES (?, ?, ?)").bind(email, code, exp).run();
          await fetch("https://api.resend.com/emails", {
            method: "POST", 
            headers: { "Authorization": "Bearer " + env.RESEND_API_KEY, "Content-Type": "application/json" },
            body: JSON.stringify({ from: "YL Accounts <no-reply@xylplay.top>", to: [email], subject: "验证码", html: "<h1>" + code + "</h1>" })
          });
          return new Response(JSON.stringify({ success: true }), { headers: corsHeaders });
        }
        if (request.method === "POST" && url.pathname === "/api/register") {
          const { nickname, email, code, password } = await request.json();
          const rec = await env.DB.prepare("SELECT * FROM verify_codes WHERE email = ? AND code = ?").bind(email, code).first();
          if (!rec) return new Response("验证码错误", { status: 400, headers: corsHeaders });
          const hash = await hashPassword(password);
          try {
            await env.DB.prepare("INSERT INTO users (email, password_hash, nickname, avatar) VALUES (?, ?, ?, '')").bind(email, hash, nickname).run();
            await env.DB.prepare("DELETE FROM verify_codes WHERE email = ?").bind(email).run();
            return new Response(JSON.stringify({ success: true }), { headers: corsHeaders });
          } catch (e) { return new Response("邮箱已注册", { status: 400, headers: corsHeaders }); }
        }
        if (request.method === "POST" && url.pathname === "/api/login") {
          const { email, password } = await request.json();
          const hash = await hashPassword(password);
          const user = await env.DB.prepare("SELECT * FROM users WHERE email = ? AND password_hash = ?").bind(email, hash).first();
          if (user) return new Response(JSON.stringify({ email: user.email, success: true }), { headers: corsHeaders });
          return new Response("密码错误", { status: 401, headers: corsHeaders });
        }
        
        // 【新增接口】从后端拉取用户最新头像和名字
        if (request.method === "GET" && url.pathname === "/api/get-profile") {
          const email = url.searchParams.get("email");
          if (!email) return new Response("Missing email", { status: 400, headers: corsHeaders });
          const user = await env.DB.prepare("SELECT nickname, avatar FROM users WHERE email = ?").bind(email).first();
          if (user) {
            return new Response(JSON.stringify({ success: true, nickname: user.nickname, avatar: user.avatar }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
          }
          return new Response(JSON.stringify({ success: false }), { headers: corsHeaders });
        }

        if (request.method === "POST" && url.pathname === "/api/profile") {
          const { email, nickname, avatar } = await request.json();
          if (!email) return new Response("Missing email", { status: 400, headers: corsHeaders });
          if (nickname !== undefined) {
            await env.DB.prepare("UPDATE users SET nickname = ? WHERE email = ?").bind(nickname, email).run();
          }
          if (avatar !== undefined) {
            await env.DB.prepare("UPDATE users SET avatar = ? WHERE email = ?").bind(avatar, email).run();
          }
          return new Response(JSON.stringify({ success: true }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
        }
        
      } catch (e) { return new Response(e.message, { status: 500, headers: corsHeaders }); }
    }
    
    const finalHTML = HTML_TEMPLATE.split('\\\${LOGO_BASE64}').join(LOGO_BASE64);
    return new Response(finalHTML, { headers: { "Content-Type": "text/html; charset=utf-8" } });
  }
};
